const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};

const event = body.event;

// Version V5.5.3 : on ne traite que message_created pour eviter les doublons.
if (event !== 'message_created') {
  return [];
}

const conversationId = (body.conversation?.id ?? '').toString();
const incomingText = (body.content ?? '').toString().trim();
const messageType = String(body.message_type ?? '').toLowerCase();

if (messageType !== '0' && messageType !== 'incoming') {
  return [];
}

if (!incomingText || !conversationId) {
  return [];
}

const senderName =
  body.sender?.name ??
  body.meta?.sender?.name ??
  body.conversation?.meta?.sender?.name ??
  'prospect';

const senderEmail =
  body.sender?.email ??
  body.meta?.sender?.email ??
  body.conversation?.meta?.sender?.email ??
  '';

const senderPhone =
  body.sender?.phone_number ??
  body.meta?.sender?.phone_number ??
  body.conversation?.meta?.sender?.phone_number ??
  '';

const fallbackReply =
  "Je n'ai pas pu generer une reponse pour le moment. Un membre de notre equipe vous contactera rapidement.";

return [{
  json: {
    conversation_id: conversationId,
    incoming_text: incomingText,
    sender_name: senderName,
    sender_email: senderEmail,
    sender_phone: senderPhone,
    fallback_reply: fallbackReply,
    source_event: event
  }
}];

const historyResponse = $input.first()?.json ?? {};
const current = $('Filter Chatwoot event').first()?.json ?? {};

const MAX_HISTORY = 20;
const CALENDLY_LINK = 'https://calendly.com/contact-transferai/30min';
const PUBLIC_DOMAIN = 'https://www.transferai.ci';

function asArray(response) {
  if (Array.isArray(response)) return response;
  if (Array.isArray(response.payload)) return response.payload;
  if (Array.isArray(response.data)) return response.data;
  if (Array.isArray(response.messages)) return response.messages;
  return [];
}

const messages = asArray(historyResponse)
  .map((m) => {
    const content = (m.content ?? '').toString().trim();
    if (!content) return null;
    const isIn = m.message_type === 0 || m.message_type === 'incoming' || m.message_type === 3;
    const isOut = m.message_type === 1 || m.message_type === 'outgoing';
    if (!isIn && !isOut) return null;
    return { role: isIn ? 'user' : 'assistant', content, ts: m.created_at || 0 };
  })
  .filter(Boolean)
  .sort((a, b) => a.ts - b.ts)
  .slice(-MAX_HISTORY)
  .map(({ role, content }) => ({ role, content }));

const lastUserInHistory = [...messages].reverse().find((m) => m.role === 'user')?.content ?? '';
const alreadyIncluded = lastUserInHistory === current.incoming_text;

const knownEmail = (current.sender_email || '').toString().trim();
const contactInfoStatus = knownEmail
  ? `L'email du prospect est deja connu : ${knownEmail}. Ne le redemande surtout pas.`
  : "L'email du prospect n'est pas encore connu.";

const systemPrompt = [
  "Tu es l'assistant commercial et d'orientation de TransferAI Africa.",
  "Tu reponds en francais ou en anglais selon la langue du DERNIER message du prospect.",
  "Ne mentionne jamais que tu changes de langue.",
  "Tu representes une organisation centree sur la formation IA, l'accompagnement entreprise, l'audit IA, la veille strategique, l'automatisation, les catalogues sectoriels, les certifications, les webinaires et certains partenariats.",
  "Tu dois t'appuyer uniquement sur ces verites metier. N'invente jamais d'offre, de prix, de calendrier, de reference client ou de promesse non confirmee.",
  "Tu disposes de l'historique recent. Utilise-le pour eviter de reposer les memes questions.",
  "Quand le besoin est simple, reponds d'abord utilement puis pose UNE seule question de qualification pertinente.",
  "Quand le besoin est plus large, pose au maximum DEUX questions de qualification par reponse.",
  "Questions de qualification prioritaires : organisation ou entreprise, secteur, objectif principal, email, site web.",
  "Regle contact importante : " + contactInfoStatus,
  "Regle rendez-vous : si le prospect demande explicitement un rendez-vous, un creneau, un appel, une demo, un echange avec l'equipe, une discussion cette semaine ou un accompagnement, donne IMMEDIATEMENT ce lien de reservation : " + CALENDLY_LINK,
  "Tu peux demander l'email dans la meme reponse pour le suivi, mais jamais comme condition prealable au partage du lien.",
  "Si le prospect demande les tarifs, explique brievement que l'orientation depend du besoin et propose un echange ou la collecte du contexte. N'invente aucun prix.",
  "Si la demande concerne emploi ou candidature, oriente vers la voie emploi et mise en relation plutot que vers une vente classique.",
  "Si la demande concerne support ou acces technique, propose une reprise humaine.",
  "Si tu cites le site, utilise seulement des liens publics coherents avec TransferAI, par exemple " + PUBLIC_DOMAIN + ", /entreprises, /catalogue, /contact.",
  "Ton style : chaleureux, professionnel, clair, concret, sans jargon excessif.",
  "Ta reponse doit tenir en maximum 6 lignes courtes, avec une seule action principale a la fin."
].join(' ');

const openaiMessages = [{ role: 'system', content: systemPrompt }, ...messages];

if (!alreadyIncluded) {
  openaiMessages.push({ role: 'user', content: current.incoming_text });
}

return [
  {
    json: {
      conversation_id: current.conversation_id,
      incoming_text: current.incoming_text,
      sender_name: current.sender_name,
      sender_email: current.sender_email,
      sender_phone: current.sender_phone,
      fallback_reply: current.fallback_reply,
      history_count: messages.length,
      raw_history_messages: messages,
      openai_payload: {
        model: 'gpt-4.1-mini',
        temperature: 0.25,
        max_tokens: 420,
        messages: openaiMessages
      }
    }
  }
];

const openai = $input.first()?.json ?? {};
const context = $('Build OpenAI reply payload').first()?.json ?? {};

const replyText =
  openai.choices?.[0]?.message?.content?.toString().trim() ||
  context.fallback_reply ||
  "Je n'ai pas pu g\u00e9n\u00e9rer une r\u00e9ponse. Un agent humain va vous contacter.";

return [{
  json: {
    ...context,
    reply_text: replyText
  }
}];

const openai = $input.first()?.json ?? {};
const context = $('Build qualification payload').first()?.json ?? {};

const DEFAULT_QUALIFICATION = {
  company_name: null,
  sector: null,
  need_type: null,
  intent: null,
  lead_seriousness: null,
  is_b2b: null,
  wants_demo: null,
  needs_human_handoff: null,
  contact_name: null,
  email: null,
  phone: null,
  website: null,
  country: null,
  summary: null,
  next_best_action: null,
  crm_readiness_level: 'none',
  recommended_workflow: null,
  missing_fields: ['company_name', 'sector', 'need_type', 'email', 'website']
};

let qualification = { ...DEFAULT_QUALIFICATION };
let parseError = null;

try {
  const raw = openai.choices?.[0]?.message?.content?.toString().trim() || '{}';
  const parsed = JSON.parse(raw);
  qualification = { ...DEFAULT_QUALIFICATION, ...parsed };
} catch (err) {
  parseError = err.message;
}

if (!qualification.contact_name && context.sender_name && context.sender_name !== 'prospect') {
  qualification.contact_name = context.sender_name;
}
if (!qualification.email && context.sender_email) {
  qualification.email = context.sender_email;
}
if (!qualification.phone && context.sender_phone) {
  qualification.phone = context.sender_phone;
}

const labels = [];
const intent = (qualification.intent || '').toString().toLowerCase();
if (intent === 'formation') labels.push('formation');
if (intent === 'audit_ia') labels.push('audit-ia');
if (intent === 'automatisation') labels.push('automatisation');
if (intent === 'partenariat') labels.push('partenariat');
if (intent === 'emploi') labels.push('emploi');
if (intent === 'catalogue') labels.push('catalogue');
if (intent === 'certification') labels.push('certification');
if (intent === 'webinar') labels.push('webinar');
if (intent === 'support') labels.push('support');
if (intent === 'veille') labels.push('veille');

const seriousness = (qualification.lead_seriousness || '').toString().toLowerCase();
if (seriousness === 'eleve' || seriousness === 'élevé' || seriousness === 'high') {
  labels.push('lead-chaud');
}
if (Array.isArray(qualification.missing_fields) && qualification.missing_fields.length > 0) {
  labels.push('infos-manquantes');
}
if (qualification.needs_human_handoff === true) {
  labels.push('handoff-humain');
}
if (qualification.wants_demo === true) {
  labels.push('demo-proposee');
}
if (qualification.crm_readiness_level === 'contact_request_ready') {
  labels.push('crm-contact-ready');
}
if (qualification.crm_readiness_level === 'prospect_target_ready') {
  labels.push('crm-prospect-ready');
}

const customAttributes = {};
if (qualification.contact_name) customAttributes.contact_name = qualification.contact_name;
if (qualification.company_name) customAttributes.company_name = qualification.company_name;
if (qualification.sector) customAttributes.sector = qualification.sector;
if (qualification.need_type) customAttributes.need_type = qualification.need_type;
if (qualification.intent) customAttributes.intent = qualification.intent;
if (qualification.lead_seriousness) customAttributes.lead_seriousness = qualification.lead_seriousness;
if (qualification.summary) customAttributes.internal_summary = qualification.summary;
if (qualification.next_best_action) customAttributes.next_best_action = qualification.next_best_action;
if (qualification.country) customAttributes.country = qualification.country;
if (qualification.website) customAttributes.lead_website = qualification.website;
if (qualification.crm_readiness_level) customAttributes.crm_readiness_level = qualification.crm_readiness_level;
if (qualification.recommended_workflow) customAttributes.recommended_workflow = qualification.recommended_workflow;
if (typeof qualification.is_b2b === 'boolean') customAttributes.is_b2b = qualification.is_b2b;
if (typeof qualification.wants_demo === 'boolean') customAttributes.demo_proposed = qualification.wants_demo;
if (typeof qualification.needs_human_handoff === 'boolean') customAttributes.human_handoff = qualification.needs_human_handoff;
if (qualification.email) customAttributes.lead_email = qualification.email;
if (qualification.phone) customAttributes.lead_phone = qualification.phone;

return [
  {
    json: {
      conversation_id: context.conversation_id,
      qualification,
      labels,
      labels_count: labels.length,
      custom_attributes_payload: { custom_attributes: customAttributes },
      labels_payload: { labels },
      parse_error: parseError,
      qualification_used_fallback: parseError !== null
    }
  }
];
